String source = 'A1 B22 C333';
System.assertEquals('A0 B0 C0', source.replaceAll('([A-Z]+)([0-9]+)', '$10'));
System.assertEquals('$1 B22 C333', source.replaceFirst('([A-Z]+)([0-9]+)', '\$1'));
String splitSource = ':boo:';
List<String> defaultSplit = splitSource.split(':');
System.assertEquals(2, defaultSplit.size());
System.assertEquals('', defaultSplit.get(0));
System.assertEquals('boo', defaultSplit.get(1));
List<String> keepTrailing = splitSource.split(':', -1);
System.assertEquals(3, keepTrailing.size());
System.assertEquals('', keepTrailing.get(2));
List<String> noSplit = splitSource.split(':', 1);
System.assertEquals(1, noSplit.size());
System.assertEquals(':boo:', noSplit.get(0));
Pattern colon = Pattern.compile(':');
List<String> patternKeepTrailing = colon.split(splitSource, -1);
System.assertEquals(3, patternKeepTrailing.size());
System.assertEquals('boo', patternKeepTrailing.get(1));
String escapedJava = '\141\040\u03A9';
String unescapedJava = escapedJava.unescapeJava();
System.assertEquals('a ', unescapedJava.substring(0, 2));
System.assertEquals(937, unescapedJava.codePointAt(2));
String escapedEcma = '\/';
System.assertEquals('/', escapedEcma.unescapeEcmaScript());

